void findMinMax(const int a[], int n, int &mn, int &mx) {
    mn = mx = a[0];
    for (int i = 1; i < n; ++i) {
        if (a[i] < mn) mn = a[i];
        if (a[i] > mx) mx = a[i];
    }
}

