int countNonNegativeColumns(const int a[][MAX], int R, int C) {
    int answer = 0;
    for (int j = 0; j < C; ++j) {
        bool ok = true;
        for (int i = 0; i < R; ++i) {
            if (a[i][j] < 0) {
                ok = false;
                break;
            }
        }
        if (ok) ++answer;
    }
    return answer;
}

